    test("world_location_global_and_destroyed_handles",[&]{ScriptSession session(compile({},"location start=Location(-400.0,100000.0)\n"),map().info);session.attachWorld(sessionWorld());session.configure();auto value=session.runtime().global("start");require(call(session,"GetLocationY",{value}).bits==Real::fromInteger(100000).bits(),"Location was incorrectly clamped");call(session,"MoveLocation",{value,number(session,100000),number(session,-100000)});require(call(session,"GetLocationX",{value}).bits==Real::fromInteger(100000).bits(),"Moved location was not retained");call(session,"RemoveLocation",{value});require(session.liveObjects(NativeKind::Location)==0,"Location not released");auto empty=call(session,"GetUnitLoc",{session.runtime().handle("unit",0)});require(!empty.bits && !call(session,"GetLocationX",{empty}).bits && !call(session,"GetLocationY",{empty}).bits,"Missing unit location did not yield zero coordinates");require(!call(session,"GetLocationX",{value}).bits && !call(session,"GetLocationY",{value}).bits,"Destroyed location did not yield zero coordinates");call(session,"RemoveLocation",{empty});call(session,"RemoveLocation",{value});});
    test("world_rect_query_mutation_and_full_extent",[&]{ScriptSession session(compile({},"rect selected=Rect(100.0,-500.0,-300.0,500.0)\n"),map().info);session.attachWorld(sessionWorld());session.configure();auto selected=session.runtime().global("selected");auto bounds=session.world()->bounds();auto clampX=[&](int x){return std::clamp(x,bounds.minX.toInteger(),bounds.maxX.toInteger()-32);};auto clampY=[&](int y){return std::clamp(y,bounds.minY.toInteger(),bounds.maxY.toInteger()-32);};int minX=clampX(-300),maxX=clampX(100),minY=clampY(-500),maxY=clampY(500);require(call(session,"GetRectMinX",{selected}).bits==Real::fromInteger(minX).bits() && call(session,"GetRectMaxY",{selected}).bits==Real::fromInteger(maxY).bits(),"Global rect was not bounded");require(call(session,"GetRectCenterX",{selected}).bits==Real::fromInteger((minX+maxX)/2).bits() && call(session,"GetRectCenterY",{selected}).bits==Real::fromInteger((minY+maxY)/2).bits(),"Rectangle centers differ");auto full=call(session,"GetWorldBounds",{}),other=call(session,"GetWorldBounds",{});require(full.bits!=other.bits && call(session,"GetRectMaxX",{full}).bits==bounds.maxX.bits(),"World bounds were clamped or shared as one mutable handle");auto a=call(session,"Location",{number(session,25),number(session,75)}),b=call(session,"Location",{number(session,-100),number(session,-200)});call(session,"SetRectFromLoc",{selected,a,b});require(call(session,"GetRectMinX",{selected}).bits==Real::fromInteger(clampX(-100)).bits() && call(session,"GetRectMaxY",{selected}).bits==Real::fromInteger(clampY(75)).bits(),"Location-based rect mutation differs");call(session,"RemoveRect",{selected});rejects([&]{call(session,"GetRectMinX",{selected});},"Destroyed or incompatible");});
    test("world_main_preserves_session_and_environment",[&]{auto module=compile("call SetCameraBounds(-10.0,-20.0,30.0,40.0,-10.0,40.0,30.0,-20.0)\ncall SetDayNightModels(\"Terrain.mdl\",\"Units.mdl\")\ncall SetWaterBaseColor(128,128,255,255)\n");ScriptSession session(std::move(module),map().info);rejects([&]{session.startMain();},"configured world");session.attachWorld(sessionWorld());session.configure();PlayerSetup setup(map().info,session.config());session.applySetup(setup);session.startMain();auto& e=session.world()->environment();require(session.mainCompleted() && session.configured() && session.localPlayer()==0u && e.cameraChanged && e.dayNightChanged && e.waterChanged,"Main did not keep valid session state");require(e.cameraBounds[3].bits()==Real::fromInteger(40).bits() && e.terrainDayNight=="Terrain.mdl" && e.unitDayNight=="Units.mdl" && e.waterColor==std::array<std::uint8_t,4>{128,128,255,255},"World environment mutation lost");rejects([&]{session.startMain();},"configured world");rejects([&]{session.applySetup(setup);},"before main");});
    test("world_main_failure_is_terminal",[&]{ScriptSession session(compile("call SetCameraBounds(1.0,2.0,3.0,4.0,1.0,4.0,3.0,2.0)\ncall Unavailable()\n",{},"native Unavailable takes nothing returns nothing\n"),map().info);session.attachWorld(sessionWorld());session.configure();PlayerSetup setup(map().info,session.config());session.applySetup(setup);rejects([&]{session.startMain();},"Unbound JASS native: Unavailable");require(!session.mainCompleted() && !session.configured() && session.world()->environment().cameraChanged,"Partial main was accepted or diagnostics lost");rejects([&]{session.startMain();},"configured world");rejects([&]{session.applySetup(setup);},"configured session");});
    test("world_coastal_landing_bounds",[]{MapData data;data.terrain.width=3;data.terrain.height=3;data.terrain.origin={0,0};data.terrain.corners.resize(9);data.pathing.emplace();auto& path=*data.pathing;path.width=8;path.height=8;path.cells.assign(64,64);for(unsigned y=0;y<8;++y)path.cells[size_t(y)*8+7]=2;World w(std::move(data),{});auto point=[](int x,int y){return WorldPoint{Real::fromInteger(x),Real::fromInteger(y)};};auto site=w.coastalLanding(point(224,112),point(208,112),0,0,64);require(site && site->x.bits()==Real::fromInteger(224).bits(),"Coastal landing escaped the world movement bounds");});
    test("world_coastal_landing_grid_and_invalidation",[]{MapData data;data.terrain.width=65;data.terrain.height=17;data.terrain.origin={0,0};data.terrain.corners.resize(65*17);data.pathing.emplace();auto& path=*data.pathing;path.width=256;path.height=64;path.cells.assign(size_t(path.width)*path.height,66);for(unsigned y=0;y<64;++y)for(unsigned x=0;x<200;++x)path.cells[size_t(y)*256+x]=64;for(unsigned x=200;x<=250;++x)path.cells[size_t(20)*256+x]=2;World w(std::move(data),{});auto point=[](int x,int y){return WorldPoint{Real::fromInteger(x*32+16),Real::fromInteger(y*32+16)};};auto ship=point(240,20),goal=point(10,40);auto landing=w.coastalLanding(ship,goal,0,64,128);require(landing && landing->x.bits()==point(200,20).x.bits() && landing->y.bits()==point(200,20).y.bits(),"Long one-cell channel did not find its coastal landing");require(w.coastalLanding(ship,goal,0,64,128).has_value(),"Cached coastal landing was lost");require(w.pathRegionsNear(ship,*landing,0,PathMovement::Water,32)==true && w.pathRegionsNear(goal,point(197,20),64,PathMovement::Ground,32)==true,"Coastal lookup damaged shared path regions");auto blockedGoal=w.coastalLanding(ship,point(202,20),0,64,128);require(blockedGoal && blockedGoal->x.bits()==point(201,20).x.bits(),"Blocked destination did not select a reachable ground region");w.terrainPathable(point(225,20),6,false);require(!w.coastalLanding(ship,goal,0,64,128),"Blocked water channel retained a landing");w.terrainPathable(point(225,20),6,true);require(w.coastalLanding(ship,goal,0,64,128).has_value(),"Reopened water channel retained stale failure");});
    test("world_blocked_goal_reachable_alternative",[]{auto data=map();data.pathing.emplace();auto& path=*data.pathing;path.width=32;path.height=16;path.cells.assign(size_t(path.width)*path.height,0);for(unsigned y=0;y<path.height;++y)path.cells[size_t(y)*path.width+16]=2;path.cells[size_t(8)*path.width+17]=2;path.cells[size_t(8)*path.width+27]=2;World w(std::move(data),{});auto point=[](int x,int y){return WorldPoint{Real::fromInteger(-512+x*32+16),Real::fromInteger(-256+y*32+16)};};auto from=point(14,8),target=point(17,8);auto route=w.route(from,target,0,PathMovement::Ground);require(!route.empty() && route.back().x.toInteger()==-16 && route.back().y.toInteger()==16,"Blocked target did not select the reachable side of the wall");require(w.pathSegmentFree(from,route.back(),0,PathMovement::Ground),"Alternative crosses a blocked wall");require(w.route(from,point(27,8),0,PathMovement::Ground).empty(),"Route returned a destination without a reachable candidate");});
    test("world_unreachable_goal_partial_route",[]{auto data=map();data.pathing.emplace();auto& path=*data.pathing;path.width=32;path.height=16;path.cells.assign(size_t(path.width)*path.height,0);for(unsigned y=0;y<path.height;++y)path.cells[size_t(y)*path.width+16]=2;World w(std::move(data),{});auto point=[](int x,int y){return WorldPoint{Real::fromInteger(-512+x*32+16),Real::fromInteger(-256+y*32+16)};};auto from=point(10,8),target=point(22,8);require(w.route(from,target,0,PathMovement::Ground).empty(),"Strict route accepted unreachable goal");auto route=w.route(from,target,0,PathMovement::Ground,true);require(!route.empty() && route.back().x.toInteger()==-16 && route.back().y.toInteger()==16,"Partial route did not select nearest reachable cell");for(size_t i=0;i<route.size();++i)require(w.pathSegmentFree(i?route[i-1]:from,route[i],0,PathMovement::Ground),"Partial route crossed barrier");require(w.route(point(15,8),target,0,PathMovement::Ground,true).empty(),"Partial route accepted no progress");auto direct=w.route(from,point(12,9),0,PathMovement::Ground,true);require(!direct.empty() && direct.back().x.toInteger()==-112 && direct.back().y.toInteger()==48,"Partial mode changed reachable destination");});
    test("world_failed_route_cache_invalidation",[]{auto data=map();data.pathing.emplace();auto& path=*data.pathing;path.width=32;path.height=16;path.cells.assign(size_t(path.width)*path.height,0);for(unsigned y=0;y<path.height;++y)path.cells[size_t(y)*path.width+16]=2;World w(std::move(data),{});auto point=[](int x,int y){return WorldPoint{Real::fromInteger(-512+x*32+16),Real::fromInteger(-256+y*32+16)};};auto start=point(12,8),goal=point(20,8),gap=point(16,8);require(w.route(start,goal,0,PathMovement::Ground).empty() && w.route(start,goal,0,PathMovement::Ground).empty(),"Closed wall accepted");w.terrainPathable(gap,1,true);require(!w.route(start,goal,0,PathMovement::Ground).empty(),"Opening terrain did not invalidate failed route");require(w.route(start,goal,32,PathMovement::Ground).empty(),"Narrow opening accepted large collision radius");require(!w.route(start,goal,0,PathMovement::Ground).empty(),"Radius changed another route result");w.terrainPathable(gap,1,false);require(w.route(start,goal,0,PathMovement::Ground).empty(),"Closed terrain accepted");require(!w.route(start,goal,0,PathMovement::Ground,true).empty(),"Partial route reused strict failure");w.terrainPathable(gap,1,true);auto cell=w.pathCell(float(gap.x.toInteger()),float(gap.y.toInteger()));require(cell.has_value(),"Gap cell missing");std::array<PathCell,1> obstacle{{{*cell,2}}};w.footprint(obstacle,true);require(w.route(start,goal,0,PathMovement::Ground).empty(),"Dynamic obstacle accepted");w.footprint(obstacle,false);require(!w.route(start,goal,0,PathMovement::Ground).empty(),"Removing dynamic obstacle did not invalidate failed route");});
    test("world_region_pathing_changes",[]{MapData data;data.terrain.width=33;data.terrain.height=33;data.terrain.origin={0,0};data.terrain.corners.resize(33*33);data.pathing.emplace();auto& path=*data.pathing;path.width=128;path.height=128;path.cells.assign(size_t(path.width)*path.height,0);for(unsigned y=0;y<path.height;++y)path.cells[size_t(y)*path.width+64]=2;World w(std::move(data),{});auto point=[](int x,int y){return WorldPoint{Real::fromInteger(x*32+16),Real::fromInteger(y*32+16)};};for(int y=10;y<34;y+=4)require(w.route(point(30,y),point(90,y),0,PathMovement::Ground).empty(),"Disconnected cells produced a strict route");require(!w.route(point(30,10),point(90,10),0,PathMovement::Air).empty(),"Ground barrier blocked air movement");require(!w.route(point(30,10),point(90,10),0,PathMovement::Ground,true).empty(),"Disconnected partial route was rejected");w.terrainPathable(point(64,64),1,true);auto opened=w.route(point(30,10),point(90,10),0,PathMovement::Ground);require(!opened.empty(),"Opening a region did not restore reachability");for(size_t i=0;i<opened.size();++i)require(w.pathSegmentFree(i?opened[i-1]:point(30,10),opened[i],0,PathMovement::Ground),"Restored route crossed blocked cells");require(w.route(point(30,10),point(90,10),32,PathMovement::Ground).empty(),"Narrow gap accepted large clearance");});
    test("world_partial_route_cache_invalidation",[]{auto data=map();data.pathing.emplace();auto& path=*data.pathing;path.width=32;path.height=16;path.cells.assign(size_t(path.width)*path.height,0);for(unsigned y=0;y<path.height;++y)path.cells[size_t(y)*path.width+16]=2;World w(std::move(data),{});auto point=[](int x,int y){return WorldPoint{Real::fromInteger(-512+x*32+16),Real::fromInteger(-256+y*32+16)};};auto start=point(10,8),goal=point(22,8),gap=point(16,8);auto first=w.route(start,goal,0,PathMovement::Ground,true);require(!first.empty(),"Missing partial route");auto same=w.route({Real::fromInteger(start.x.toInteger()+7),start.y},{Real::fromInteger(goal.x.toInteger()+5),goal.y},0,PathMovement::Ground,true);require(first.size()==same.size(),"Same cells changed partial route length");for(size_t i=0;i<first.size();++i)require(first[i].x.bits()==same[i].x.bits() && first[i].y.bits()==same[i].y.bits(),"Same cells changed partial route points");require(w.route(start,goal,0,PathMovement::Ground).empty(),"Strict path reused partial path");w.terrainPathable(gap,1,true);auto opened=w.route(start,goal,0,PathMovement::Ground,true);require(!opened.empty() && opened.back().x.bits()==goal.x.bits() && opened.back().y.bits()==goal.y.bits(),"Opening a wall reused a partial route");w.terrainPathable(gap,1,false);auto again=w.route(start,goal,0,PathMovement::Ground,true);require(!again.empty() && again.back().x.bits()==first.back().x.bits() && again.back().y.bits()==first.back().y.bits(),"Closing a wall lost partial route");});
    test("world_region_partial_route_equivalence",[]{MapData data;data.terrain.width=33;data.terrain.height=33;data.terrain.origin={0,0};data.terrain.corners.resize(33*33);data.pathing.emplace();auto& path=*data.pathing;path.width=128;path.height=128;path.cells.assign(size_t(path.width)*path.height,0);for(unsigned y=0;y<path.height;++y)path.cells[size_t(y)*path.width+64]=2;auto copy=data;World regions(std::move(data),{}),fresh(std::move(copy),{});auto point=[](int x,int y){return WorldPoint{Real::fromInteger(x*32+16),Real::fromInteger(y*32+16)};};auto start=point(30,10),goal=point(90,10),gap=point(64,64);auto compare=[&](bool reached){require(regions.pathRegionsNear(start,goal,0,PathMovement::Ground,0).has_value(),"Region fixture could not build labels");auto a=regions.route(start,goal,0,PathMovement::Ground,true),b=fresh.route(start,goal,0,PathMovement::Ground,true);require(!a.empty() && a.size()==b.size(),"Region labels changed partial route length");for(size_t i=0;i<a.size();++i)require(a[i].x.bits()==b[i].x.bits() && a[i].y.bits()==b[i].y.bits(),"Region labels changed route points");require((a.back().x.bits()==goal.x.bits() && a.back().y.bits()==goal.y.bits())==reached,"Fixture reached unexpected destination");};compare(false);regions.terrainPathable(gap,1,true);fresh.terrainPathable(gap,1,true);compare(true);regions.terrainPathable(gap,1,false);fresh.terrainPathable(gap,1,false);compare(false);});
    test("world_region_nearest_partial_ties",[]{auto point=[](int x,int y){return WorldPoint{Real::fromInteger(x*32+16),Real::fromInteger(y*32+16)};};for(float radius:{0.f,32.f})for(int startY:{12,60,112})for(int goalY:{20,64,104}){MapData data;data.terrain.width=33;data.terrain.height=33;data.terrain.origin={0,0};data.terrain.corners.resize(33*33);data.pathing.emplace();auto& path=*data.pathing;path.width=128;path.height=128;path.cells.assign(size_t(path.width)*path.height,0);for(unsigned y=0;y<128;++y){path.cells[size_t(y)*128+64]=2;if(y>=40 && y<88)path.cells[size_t(y)*128+48]=2;}for(unsigned x=18;x<48;++x)path.cells[size_t(48)*128+x]=2;auto copy=data;World accelerated(std::move(data),{}),fresh(std::move(copy),{});auto start=point(24,startY),goal=point(100,goalY);require(accelerated.pathRegionsNear(start,goal,radius,PathMovement::Ground,0).has_value(),"Could not build comparison regions");auto a=accelerated.route(start,goal,radius,PathMovement::Ground,true),b=fresh.route(start,goal,radius,PathMovement::Ground,true);require(a.size()==b.size(),"Nearest partial route changed length");for(size_t i=0;i<a.size();++i)require(a[i].x.bits()==b[i].x.bits() && a[i].y.bits()==b[i].y.bits(),"Nearest partial route changed tie or waypoints");}});
    test("world_region_nearest_cache_shared",[]{MapData data;data.terrain.width=33;data.terrain.height=33;data.terrain.origin={0,0};data.terrain.corners.resize(33*33);data.pathing.emplace();auto& path=*data.pathing;path.width=128;path.height=128;path.cells.assign(size_t(path.width)*path.height,0);for(unsigned y=0;y<128;++y)path.cells[size_t(y)*128+64]=2;auto source=data;World cached(std::move(data),{});auto point=[](int x,int y){return WorldPoint{Real::fromInteger(x*32+16),Real::fromInteger(y*32+16)};};auto goal=point(100,55);require(cached.pathRegionsNear(point(20,20),goal,0,PathMovement::Ground,0).has_value(),"Could not build shared regions");for(int y:{20,35,70,90}){auto freshData=source;World fresh(std::move(freshData),{});auto a=cached.route(point(20,y),goal,0,PathMovement::Ground,true),b=fresh.route(point(20,y),goal,0,PathMovement::Ground,true);require(a.size()==b.size() && !a.empty(),"Shared nearest target changed route size");for(size_t i=0;i<a.size();++i)require(a[i].x.bits()==b[i].x.bits() && a[i].y.bits()==b[i].y.bits(),"Shared nearest target changed route");}});
    test("world_region_nearest_search_budget",[]{MapData data;data.terrain.width=129;data.terrain.height=129;data.terrain.origin={0,0};data.terrain.corners.resize(129*129);data.pathing.emplace();auto& path=*data.pathing;path.width=512;path.height=512;path.cells.assign(size_t(path.width)*path.height,0);for(unsigned y=0;y<512;++y)path.cells[size_t(y)*512+320]=2;auto copy=data;World accelerated(std::move(data),{}),fresh(std::move(copy),{});auto point=[](int x,int y){return WorldPoint{Real::fromInteger(x*32+16),Real::fromInteger(y*32+16)};};auto start=point(12,255),goal=point(480,255);require(accelerated.pathRegionsNear(start,goal,0,PathMovement::Ground,0).has_value(),"Could not build large comparison regions");auto a=accelerated.route(start,goal,0,PathMovement::Ground,true),b=fresh.route(start,goal,0,PathMovement::Ground,true);require(!a.empty() && a.size()==b.size(),"Search budget changed nearest partial route size");for(size_t i=0;i<a.size();++i)require(a[i].x.bits()==b[i].x.bits() && a[i].y.bits()==b[i].y.bits(),"Search budget changed nearest partial route");});
    test("world_success_route_cache_exact_targets",[]{auto data=map();data.pathing.emplace();auto& path=*data.pathing;path.width=32;path.height=16;path.cells.assign(size_t(path.width)*path.height,0);for(unsigned y=0;y<11;++y)path.cells[size_t(y)*path.width+16]=2;auto copy=data;World cached(std::move(data),{}),fresh(std::move(copy),{});auto point=[](int x,int y){return WorldPoint{Real::fromInteger(-512+x*32+16),Real::fromInteger(-256+y*32+16)};};auto from=point(10,8),goal=point(22,8);auto first=cached.route(from,goal,31,PathMovement::Ground);require(first.size()>1,"Fixture did not exercise an obstructed successful path");WorldPoint shiftedFrom{Real::fromInteger(from.x.toInteger()+5),from.y},shiftedGoal{Real::fromInteger(goal.x.toInteger()+7),Real::fromInteger(goal.y.toInteger()+4)};auto second=cached.route(shiftedFrom,shiftedGoal,32,PathMovement::Ground);auto expected=fresh.route(shiftedFrom,shiftedGoal,32,PathMovement::Ground);require(second.size()==expected.size() && !second.empty(),"Equivalent clearance changed successful path size");for(size_t i=0;i<second.size();++i)require(second[i].x.bits()==expected[i].x.bits() && second[i].y.bits()==expected[i].y.bits(),"Cached successful path differed from a fresh query");require(second.back().x.bits()==shiftedGoal.x.bits() && second.back().y.bits()==shiftedGoal.y.bits(),"Cached path did not retain the precise destination");for(unsigned y=11;y<16;++y)cached.terrainPathable(point(16,int(y)),1,false);require(cached.route(shiftedFrom,shiftedGoal,32,PathMovement::Ground).empty(),"New wall did not invalidate successful path");});
    test("world_original_archive_ownership_and_settings",[&]{Archives archives(argv[1]);archives.mountMap(fs::path(argv[1])/L"Maps/(2)BootyBay.w3m");auto w=World::read(archives);archives.unmountMap();require(w->data().terrain.width>2 && w->data().pathing && w->data().terrain.corners.size()==size_t(w->data().terrain.width)*w->data().terrain.height,"World lost source terrain/pathing after unmount");require(w->cameraMargin(0).bits()==Real::fromInteger(512).bits() && w->cameraMargin(2).bits()==Real::fromInteger(256).bits(),"Original MiscData margins differ");});
    if(!failed && filter.empty()){auto output=fs::absolute(argv[2]);fs::create_directories(output.parent_path());std::ofstream file(output,std::ios::binary);require(bool(file),"Cannot save world clamp fixture");file<<"{\"bounds\":[";auto w=world();bool comma=false;for(auto value:{w->bounds().minX,w->bounds().minY,w->bounds().maxX,w->bounds().maxY}){if(comma)file<<',';comma=true;file<<value.bits();}file<<"],\"cases\":[";comma=false;for(float x:{-20000.f,-512.f,-511.5f,-256.f,-0.f,0.f,.125f,224.f,255.f,256.f,479.f,480.f,481.f,512.f,20000.f})for(float y:{-20000.f,-512.f,-256.f,-255.5f,-0.f,0.f,.125f,223.f,224.f,225.f,256.f,512.f,20000.f}){WorldPoint input{Real::fromBits(std::bit_cast<std::uint32_t>(x)),Real::fromBits(std::bit_cast<std::uint32_t>(y))};auto result=w->clamp(input);if(comma)file<<',';comma=true;file<<'['<<input.x.bits()<<','<<input.y.bits()<<','<<result.x.bits()<<','<<result.y.bits()<<']';}file<<"]}\n";file.close();require(bool(file),"Cannot complete world clamp fixture");}
